<?php
require_once __DIR__ . '/includes/layout.php'; require_once __DIR__ . '/config/database.php'; checkRole(['ADMIN']); $db=getDB(); $escolinha=currentEscolinhaId(); $edit=null;
if($_SERVER['REQUEST_METHOD']==='POST'){checkCsrf();$action=$_POST['action']??'';$id=(int)($_POST['id']??0);if($action==='delete'){if($id===(int)$_SESSION['user_id']){flash('error','Você não pode excluir seu próprio usuário.');}else{$db->prepare('DELETE FROM TB_USUARIO WHERE COD_USUARIO=? AND COD_ESCOLINHA=?')->execute([$id,$escolinha]);flash('success','Usuário excluído.');}go('usuarios.php');}$nome=trim($_POST['nome']??'');$email=trim($_POST['email']??'');$perfil=$_POST['perfil']??'';$senha=$_POST['senha']??'';$ativo=isset($_POST['ativo'])?1:0;if($nome===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||!in_array($perfil,['ADMIN','SECRETARIA','PROFESSOR','RESPONSAVEL'],true)||($action==='create'&&strlen($senha)<6)){flash('error','Informe nome, e-mail válido, perfil e senha de ao menos 6 caracteres para um novo usuário.');go('usuarios.php'.($id?'?editar='.$id:''));}try{if($action==='create'){$db->prepare('INSERT INTO TB_USUARIO (COD_ESCOLINHA,NOME,EMAIL,SENHA_HASH,PERFIL,ATIVO) VALUES (?,?,?,?,?,?)')->execute([$escolinha,$nome,$email,password_hash($senha,PASSWORD_DEFAULT),$perfil,$ativo]);flash('success','Usuário cadastrado.');}elseif($action==='update'){if($senha!==''){$db->prepare('UPDATE TB_USUARIO SET NOME=?,EMAIL=?,PERFIL=?,ATIVO=?,SENHA_HASH=? WHERE COD_USUARIO=? AND COD_ESCOLINHA=?')->execute([$nome,$email,$perfil,$ativo,password_hash($senha,PASSWORD_DEFAULT),$id,$escolinha]);}else{$db->prepare('UPDATE TB_USUARIO SET NOME=?,EMAIL=?,PERFIL=?,ATIVO=? WHERE COD_USUARIO=? AND COD_ESCOLINHA=?')->execute([$nome,$email,$perfil,$ativo,$id,$escolinha]);}flash('success','Usuário atualizado.');}}catch(PDOException $e){flash('error','Já existe um usuário com este e-mail.');}go('usuarios.php');}
if(isset($_GET['editar'])){$q=$db->prepare('SELECT * FROM TB_USUARIO WHERE COD_USUARIO=? AND COD_ESCOLINHA=?');$q->execute([(int)$_GET['editar'],$escolinha]);$edit=$q->fetch();if(!$edit){flash('error','Usuário não encontrado.');go('usuarios.php');}}$q=$db->prepare('SELECT COD_USUARIO,NOME,EMAIL,PERFIL,ATIVO FROM TB_USUARIO WHERE COD_ESCOLINHA=? ORDER BY NOME');$q->execute([$escolinha]);$lista=$q->fetchAll();pageStart('Usuários');
?>
<section><h2><?=$edit?'Editar usuário':'Novo usuário'?></h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="action" value="<?=$edit?'update':'create'?>"><?php if($edit):?><input type="hidden" name="id" value="<?=(int)$edit['COD_USUARIO']?>"><?php endif;?><label>Nome<input required name="nome" value="<?=e($edit['NOME']??'')?>"></label><label>E-mail<input required type="email" name="email" value="<?=e($edit['EMAIL']??'')?>"></label><label>Perfil<select name="perfil"><?php foreach(['ADMIN'=>'Administrador','SECRETARIA'=>'Secretaria','PROFESSOR'=>'Professor','RESPONSAVEL'=>'Responsável'] as $v=>$l):?><option value="<?=$v?>" <?=($edit['PERFIL']??'')===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select></label><label>Senha <?=$edit?'(deixe vazia para manter)':''?><input <?=$edit?'':'required'?> type="password" name="senha" minlength="6"></label><label><input type="checkbox" name="ativo" <?=($edit['ATIVO']??1)?'checked':''?>> Usuário ativo</label><div><?php actionButton($edit?'Salvar alterações':'Cadastrar usuário');?><?php if($edit):?><a href="usuarios.php">Cancelar</a><?php endif;?></div></form></section><section><table><thead><tr><th>Nome</th><th>E-mail</th><th>Perfil</th><th>Estado</th><th>Ações</th></tr></thead><tbody><?php foreach($lista as $u):?><tr><td><?=e($u['NOME'])?></td><td><?=e($u['EMAIL'])?></td><td><?=e($u['PERFIL'])?></td><td><?=$u['ATIVO']?'Ativo':'Inativo'?></td><td><button type="button" class="acao-tabela" data-modal-url="usuarios.php?mini=1&amp;editar=<?=(int)$u['COD_USUARIO']?>" data-modal-titulo="Editar usuário">Editar</button><?php if($u['COD_USUARIO']!=$_SESSION['user_id']):?><form method="post" onsubmit="return confirm('Excluir este usuário?');"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$u['COD_USUARIO']?>"><button>Excluir</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></section><?php pageEnd();?>
